name: Auto-triage new issues

on:
  issues:
    types: [opened]

permissions:
  issues: write

jobs:
  triage-issue:
    runs-on: ubuntu-latest
    steps:
      - name: Bootstrap labels
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const labels = [
              { name: 'bug', color: 'e11d21' },
              { name: 'feature-request', color: '84b6eb' },
              { name: 'priority: high', color: 'eb6420' },
              { name: 'priority: medium', color: 'fef2c0' },
              { name: 'priority: low', color: '009800' }
            ];

            for (const label of labels) {
              try {
                await github.rest.issues.createLabel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  name: label.name,
                  color: label.color
                });
                console.log(`Created label: ${label.name}`);
              } catch (error) {
                if (error.status !== 422) {
                  throw error;
                }
                console.log(`Label already exists: ${label.name}`);
              }
            }

      - name: Classify issue and assign labels
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const issue = context.payload.issue;
            const title = issue.title.toLowerCase();
            const body = issue.body ? issue.body.toLowerCase() : '';
            const content = `${title} ${body}`;

            let issueType = 'feature-request';
            let priority = 'priority: medium';

            // Bug keywords
            const bugKeywords = [
              'bug', 'error', 'crash', 'broken', 'fix', 'fail', 'wrong', 'regression'
            ];

            // Feature keywords
            const featureKeywords = [
              'feat', 'feature', 'enhancement', 'add', 'implement', 'request', 'improve'
            ];

            // High priority keywords
            const highPriorityKeywords = [
              'critical', 'urgent', 'blocker', 'blocking', 'severe', 'p0', 'p1'
            ];

            // Low priority keywords
            const lowPriorityKeywords = [
              'minor', 'trivial', 'nice to have', 'low priority', 'p3', 'p4'
            ];

            // Check for bug vs feature
            const hasBugKeyword = bugKeywords.some(keyword => content.includes(keyword));
            const hasFeatureKeyword = featureKeywords.some(keyword => content.includes(keyword));

            if (hasBugKeyword) {
              issueType = 'bug';
            } else if (hasFeatureKeyword) {
              issueType = 'feature-request';
            }

            // Check for priority
            const hasHighPriorityKeyword = highPriorityKeywords.some(keyword => content.includes(keyword));
            const hasLowPriorityKeyword = lowPriorityKeywords.some(keyword => content.includes(keyword));

            if (hasHighPriorityKeyword) {
              priority = 'priority: high';
            } else if (hasLowPriorityKeyword) {
              priority = 'priority: low';
            }

            // Apply labels
            const labelsToApply = [issueType, priority];

            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: issue.number,
              labels: labelsToApply
            });

            console.log(`Applied labels: ${labelsToApply.join(', ')}`);
```

